code.java:
class Solution {
    public List<String> cellsInRange(String s){
        List<String> answer=new ArrayList<>();
        for(char column=s.charAt(0);column<=s.charAt(3);column++)for(char row=s.charAt(1);row<=s.charAt(4);row++)answer.add(""+column+row);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun cellsInRange(s:String):List<String>{
        val answer=mutableListOf<String>();
        for(column in s[0]..s[3])for(row in s[1]..s[4])answer.add("$column$row");
        return answer
    }
}

code.cpp:
class Solution {
    public:vector<string> cellsInRange(string s){
        vector<string> answer;
        for(char column=s[0];column<=s[3];++column)for(char row=s[1];row<=s[4];++row)answer.push_back(string()+column+row);
        return answer;
    }
};
